import {WorkQueue} from './work-queue.mjs';
test('队列任务释放幂等，旧任务结束不减少新任务',()=>{const q=new WorkQueue();const old=q.begin('old');q.clear();const fresh=q.begin('fresh');old.end();old.end();assert.equal(q.size,1);fresh.end();assert.equal(q.size,0);});
test('看门狗识别超时并保留任务阶段',()=>{let now=0,expired=0;const q=new WorkQueue({now:()=>now,onExpire:()=>expired++});const job=q.begin('model','group:test',100);job.stage('等待模型');now=101;q.sweep();assert.equal(expired,1);assert.equal(q.inspect().active[0].stage,'等待模型');});
