test('猫图与离开消息各自引用原消息，未知ref拒绝旧index不猜引用',()=>{const items=batchMessages([{user:'12345678',messageID:'1',text:'你知道是谁开发的你吗'},{user:'12345678',messageID:'2',text:'[收到图片]',images:['https://gchat.qpic.cn/a']},{user:'12345678',messageID:'3',text:'我刷视频去了'}]);assert.equal(messageTargets(items).length,3);const answers=parseTargetAnswers('{"answers":[{"replyTo":"u0m1","action":"send","messages":["这猫有点邪门"]},{"replyTo":"u0m2","action":"send","messages":["去吧"]}]}',items);assert.equal(answers[0].messageID,'2');assert.equal(answers[1].messageID,'3');assert.throws(()=>parseTargetAnswers('{"answers":[{"replyTo":"u9m9","action":"send","messages":["x"]}]}',items));assert.equal(parseTargetAnswers('{"answers":[{"index":0,"action":"send","messages":["x"]}]}',items)[0].quotePending,false);});
