test('LangSearch固定HTTPS接口密钥只在请求头，结果受限且不外发错误体',async()=>{const result=await langSearch('公开关键词',{key:'test-only',request:async(url,o)=>{assert.equal(url,'https://api.langsearch.com/v1/web-search');assert.equal(o.redirect,'error');assert.equal(o.headers.Authorization,'Bearer test-only');assert.equal(JSON.parse(o.body).query,'公开关键词');assert.ok(!o.body.includes('test-only'));return new Response(JSON.stringify({data:{webPages:{value:[{name:'来源',url:'https://example.com',text:'内容'},{url:'file:///secret'}]}}}));}});assert.equal(result.results.length,1);assert.equal(result.results[0].snippet,'内容');await assert.rejects(langSearch('词',{key:'test',request:async()=>new Response('secret',{status:401})}),/HTTP 401/);});
