test('必应两轮搜索按结果继续，最多四词且最终保持调用方协议',async()=>{let calls=0;const searched=[];const raw=await bingConversation(async p=>{calls++;assert.ok(p.includes('answers'));return calls===1?' {"searches":["公开词 梗"]}':calls===2?'{"searches":["公开词 视频"]}':'{"answers":[]}';},{run:async qs=>{searched.push(...qs);return qs.map(query=>({query,status:'ok',results:[]}));}},'最终输出answers');assert.equal(calls,3);assert.equal(searched.length,2);assert.equal(raw,'{"answers":[]}');});
