test('交流偏好仅从开启档案的本人分区原话筛选',()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'nikolink-pref-'));const c={...config(),userMemory:true,mode:'reply'};const p=new UserProfiles(dir,()=>c);const r={user:'12345678',key:'group:99999999',text:'请回答简短一点'};p.ingest(r,{engaged:true});const v=JSON.parse(p.prompt(r));assert.equal(v.preferences[0].text,r.text);assert.equal(p.prompt({...r,key:'private:12345678'}),'');c.userMemory=false;assert.equal(p.prompt(r),'');});
