test('群消息按人合批排序并绑定原消息引用，拒绝模型指定额外目标',()=>{const items=batchMessages([{user:'12345678',text:'问题一',messageID:'101'},{user:'23456789',text:'问题二',messageID:'102'},{user:'12345678',text:'补充',messageID:'103'}]);assert.equal(items.length,2);assert.equal(items[0].messageID,'101');assert.ok(items[0].text.includes('补充'));const answers=parseBatch('{"answers":[{"index":1,"action":"send","messages":["二"]},{"index":0,"action":"send","messages":["一"]}]}',2);assert.equal(answers[0].index,0);assert.throws(()=>parseBatch('{"answers":[{"index":9,"action":"send","messages":["x"]}]}',2));assert.deepEqual(replySegments({group:true,quotePending:true,messageID:'101'},'回答')[0],{type:'reply',data:{id:'101'}});assert.equal(replySegments({group:true,quotePending:false,messageID:'101'},'回答').length,1);});
