test('群聊实际生成使用当前发言人档案，而非群内其他人的私聊',async()=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'nikolink-users-runtime-'));fs.mkdirSync(path.join(root,'state'));const store=new Store(path.join(root,'state'));store.value={...store.value,...config(),mode:'reply',userMemory:true,groupEnabled:true};let received;
 const host={ready:true,reply:async(r,c,o)=>{received={r,o};return '{"action":"silent"}';}};const runtime=new Runtime(root,store,host,async()=>{}, {pending:0,sent:0});store.value.socialMode='v2';const r={key:'group:34567890',group:true,target:'34567890',user:'23456789',text:'我喜欢象棋',direct:true};runtime.profiles.ingest({...r,key:'private:23456789',group:false,text:'这是私聊秘密'},{engaged:true});runtime.profiles.ingest(r,{engaged:true});runtime.enqueue(r);await runtime.tail;assert.ok(received.o.userProfile.includes('我喜欢象棋'));assert.ok(!received.o.userProfile.includes('私聊秘密'));assert.equal(received.r.user,'23456789');
});
