  const runtime={work:new WorkQueue(),data:{},store:{value:c,save(){}},status:{pending:0,sent:0},epoch:0,save(){},record(){},send:async()=>{attempts++;throw Error('network');},bili:{data:{history:[{bv:'BV1234567890',author:'央视新闻',title:'国务院新闻发布会'}]},shareText:()=> 'https://www.bilibili.com/video/BV1234567890'}};
  const g=new GroupShare(runtime);g.reconnect();await assert.rejects(g.share('34567890',true));assert.equal(attempts,1);assert.equal(g.state('34567890').consumed,true);
  g.activity({post_type:'message',message_type:'group',group_id:34567890,user_id:12345678,self_id:99999999,message:[{type:'image'}]});assert.equal(g.state('34567890').consumed,false);assert.ok(g.state('34567890').lastHumanAt>0);await assert.rejects(g.share('99999999',true));assert.equal(attempts,1);
