test('分享仅链接，过滤非新闻缓存及不匹配来源', () => {
  assert.equal(newsVideo({author:'央视新闻',title:'国务院新闻发布会'}),true);
  assert.equal(newsVideo({author:'普通UP',title:'国家新闻'}),false);
  assert.equal(newsVideo({author:'央视新闻',title:'奶奶的皱纹里藏着甜与暖'}),false);
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'nikolink-news-'));const b=new BiliReadonly(dir,()=>({biliEnabled:true}));
  b.data.history=[{bv:'BV1234567890',author:'央视新闻',title:'国务院新闻发布会'},{bv:'BVabcdefghij',author:'普通UP',title:'生活记录'}];
  assert.equal(b.shareText('BV1234567890'),'https://www.bilibili.com/video/BV1234567890');assert.throws(()=>b.shareText('BVabcdefghij'));
});

