test('首页推荐要求本机账号，不调用热门榜且只向固定B站接口带凭据', async () => { const dir=fs.mkdtempSync(path.join(os.tmpdir(),'nikolink-home-'));const calls=[];const b=new BiliReadonly(dir,()=>({biliEnabled:true}),async(url,opt)=>{calls.push({url:String(url),opt});return {ok:true,text:async()=>JSON.stringify({code:0,data:String(url).includes('/rcmd?')?{item:[]}:{}})};});await assert.rejects(b.browse(),/扫码登录/);assert.equal(calls.length,0);b.account.value={sessdata:'fixture-session-not-real'};await assert.rejects(b.browse(),/首页暂无/);assert.equal(calls.length,1);assert.ok(calls[0].url.includes('/index/top/rcmd'));assert.equal(calls[0].opt.headers.Cookie,'SESSDATA=fixture-session-not-real');assert.equal(JSON.stringify(b.account.status()).includes('fixture-session'),false); });
test('分条逐条检查暂停，只统计成功发送，异常不重试', async () => { const sent=[];let enabled=true; await sendBurst(['a','b','c'],{allowed:()=>enabled,send:async t=>sent.push(t),onSent:()=>{},wait:async()=>{enabled=false;}});assert.deepEqual(sent,['a']);const attempted=[];const confirmed=[];await assert.rejects(sendBurst(['a','b','c'],{allowed:()=>true,send:async t=>{attempted.push(t);if(t==='b')throw Error('failed');},onSent:t=>confirmed.push(t),wait:async()=>{}}));assert.deepEqual(attempted,['a','b']);assert.deepEqual(confirmed,['a']); });

