test('统一控制台导航与页面一致、元素 ID 唯一', () => {
  const html = fs.readFileSync(fileURLToPath(new URL('../public/console-opencode.html', import.meta.url)), 'utf8');
  const views = [...html.matchAll(/data-view="([^"]+)"/g)].map(m => m[1]);
  const pages = [...new Set([...html.matchAll(/data-page="([^"]+)"/g)].map(m => m[1]))];
  assert.deepEqual([...views].sort(), pages.sort());
  const ids = [...html.matchAll(/\bid="([^"]+)"/g)].map(m => m[1]); assert.equal(ids.length, new Set(ids).size);
  const js = fs.readFileSync(fileURLToPath(new URL('../public/console-opencode.js', import.meta.url)), 'utf8');
  for (const [, name] of js.matchAll(/querySelector\('#([^']+)'\)/g)) assert.ok(ids.includes(name), `缺少元素 ${name}`);
  assert.ok(!html.includes('iframe')); assert.ok(!js.includes('innerHTML'));
});
