test('B站固定只读 GET，无 Cookie，拒绝其他地址及写接口', async () => { const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'nikolink-bili-')); const calls = []; const client = new BiliReadonly(dir, () => ({ biliEnabled: true }), async (url, options) => { calls.push({ url: String(url), options }); return { ok: true, text: async () => JSON.stringify({ code: 0, data: String(url).includes('/view?') ? { aid: 123, title: '视频标题', desc: '简介', owner: { name: 'UP' } } : { replies: [{ content: { message: '公开评论' } }] } }) }; }); await assert.rejects(client.get('/x/web-interface/coin/add', {})); await assert.rejects(client.get('https://evil.example', {})); assert.throws(() => videoID('https://evil.example/video/BV1234567890')); const item = await client.browse('BV1234567890'); assert.equal(item.comments[0], '公开评论'); assert.equal(calls.length, 2); for (const call of calls) { assert.equal(call.options.method, 'GET'); assert.equal(call.options.headers.Cookie, undefined); assert.equal(call.options.headers.cookie, undefined); assert.ok(call.url.startsWith('https://api.bilibili.com/')); } });

